from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    out = [[0 for _ in row] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    # The enclosed region is the only filled area; retain the original figure.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == fg:
                out[r][c] = fg
    return out

